## Why This Is Asked
This evaluates your ability to design pragmatic tooling that ensures prompt reliability without requiring complex NLP infrastructure, focusing on version control and output consistency.

## Key Concepts
- Semantic prompt versioning and management
- Output determinism validation through stable hashing
- Delta scoring for output comparison
- Lightweight testing frameworks
- Performance observability

## Code Example
```javascript
// Minimal prototype showing two prompts and hash comparison
const crypto = require('crypto');

function hash(obj) {
  return crypto.createHash('sha256').update(JSON.stringify(obj)).digest('hex');
}

function calculateDelta(output1, output2) {
  const hash1 = hash(output1);
  const hash2 = hash(output2);
  return hash1 === hash2 ? 0 : 1;
}

const prompts = {
  v1: 'Get monthly signup counts by region',
  v2: 'Calculate monthly user signups organized by geographic region'
};

function mockLLM(prompt) {
  return { data: `Response for: ${prompt}`, timestamp: Date.now() };
}

function selectVersion() {
  const outputs = {
    v1: mockLLM(prompts.v1),
    v2: mockLLM(prompts.v2)
  };

  const delta = calculateDelta(outputs.v1, outputs.v2);
  const selectedVersion = delta === 0 ? 'v1' : 'v2';

  return {
    selectedVersion,
    payload: outputs[selectedVersion],
    deltaScore: delta
  };
}

console.log(selectVersion());
```

## Implementation Notes
The system uses SHA-256 hashing for deterministic output comparison and a simple delta score to measure consistency between versions.

## Why This Is Asked

Tests ability to design end-to-end prompt orchestration under SLA; covers multi-model choice, caching, and budget-based pruning in a multi-tenant context.

## Key Concepts

- Dynamic plan generation with per-model latency and cost profiles
- Content-addressable caching to reduce repeated work
- Budget-aware pruning and graceful degradation
- Tenant isolation and guardrails in orchestration

## Code Example

```javascript
class MockModel {
  constructor(name, tokenCost, latencyMs){
    this.name = name; this.tokenCost = tokenCost; this.latencyMs = latencyMs;
  }
  run(prompt){
    return new Promise(resolve => setTimeout(() => resolve(`${this.name}-out:${prompt.slice(0,60)}`), this.latencyMs));
  }
}

const modelA = new MockModel('ModelA', 0.5, 120);
const modelB = new MockModel('ModelB', 0.2, 60);
const cache = new Map();
function hash(s){ let h=0; for(let i=0;i<s.length;i++){ h=(h<<5)-h+s.charCodeAt(i); h|=0;} return h.toString(); }
function plan(intent){ return [ [modelA, intent+" [segment1]"], [modelB, intent+" [segment2]"] ]; }
async function runPlan(intent, budgetTokens, maxLatencyMs=300){
  const key = hash(intent);
  if(cache.has(key)) return cache.get(key);
  const steps = plan(intent);
  let totalLatency = 0; const outputs = [];
  for(const [m,p] of steps){ const out = await m.run(p); outputs.push(out); totalLatency += m.latencyMs; if(totalLatency>maxLatencyMs) break; }
  const result = outputs.join(' | ');
  cache.set(key, result);
  return result;
}
```
